{"file_text":"import { DefaultAzureCredential } from '@azure/identity';
import { BlobServiceClient } from '@azure/storage-blob';
import { KeyClient } from '@azure/keyvault-keys';

export interface AzureConfig {
  credential: DefaultAzureCredential;
  blobServiceClient: BlobServiceClient;
  keyClient: KeyClient;
  keyName: string;
  containerName: string;
}

export function createAzureConfig(): AzureConfig {
  // Read configuration from environment variables
  const storageAccountName = process.env.AZURE_STORAGE_ACCOUNT_NAME;
  const keyVaultUrl = process.env.AZURE_KEY_VAULT_URL;
  const keyName = process.env.AZURE_KEY_VAULT_KEY_NAME || 'encryption-key';
  const containerName = process.env.AZURE_STORAGE_CONTAINER_NAME || 'encrypted-files';

  if (!storageAccountName) {
    throw new Error('AZURE_STORAGE_ACCOUNT_NAME environment variable is required');
  }

  if (!keyVaultUrl) {
    throw new Error('AZURE_KEY_VAULT_URL environment variable is required');
  }

  // Create a single shared credential instance
  const credential = new DefaultAzureCredential();

  // Build Blob Storage connection
  const blobServiceUrl = `https://${storageAccountName}.blob.core.windows.net`;
  const blobServiceClient = new BlobServiceClient(blobServiceUrl, credential);

  // Build Key Vault connection
  const keyClient = new KeyClient(keyVaultUrl, credential);

  return {
    credential,
    blobServiceClient,
    keyClient,
    keyName,
    containerName,
  };
}
