{"file_text":"import { KeyClient } from '@azure/keyvault-keys';
import { createCipheriv, createDecipheriv, randomBytes } from 'crypto';

export interface WrappedKey {
  wrappedKey: string; // Base64-encoded wrapped DEK
  keyId: string; // Key Vault key ID used for wrapping
}

export interface EncryptionResult {
  ciphertext: Buffer;
  iv: string; // Base64-encoded initialization vector
  authTag: string; // Base64-encoded authentication tag
  wrappedKey: WrappedKey;
}

export class KeyManager {
  private keyClient: KeyClient;
  private keyName: string;

  constructor(keyClient: KeyClient, keyName: string) {
    this.keyClient = keyClient;
    this.keyName = keyName;
  }

  /**
   * Generates a random data encryption key (DEK) for AES-256-GCM
   */
  private generateDataKey(): Buffer {
    // Generate a 256-bit (32-byte) key for AES-256
    return randomBytes(32);
  }

  /**
   * Wraps (encrypts) a data encryption key using Key Vault
   */
  private async wrapKey(dataKey: Buffer): Promise<WrappedKey> {
    try {
      const key = await this.keyClient.getKey(this.keyName);

      if (!key.key) {
        throw new Error('Key not found in Key Vault');
      }

      // Use Key Vault to wrap the DEK
      const cryptoClient = this.keyClient.getCryptographyClient(key.name, { keyVersion: key.properties.version });
      const wrapResult = await cryptoClient.wrapKey('RSA-OAEP', dataKey);

      return {
        wrappedKey: Buffer.from(wrapResult.result).toString('base64'),
        keyId: key.id!,
      };
    } catch (error) {
      throw new Error(`Failed to wrap key: ${error instanceof Error ? error.message : String(error)}`);
    }
  }

  /**
   * Unwraps (decrypts) a data encryption key using Key Vault
   */
  private async unwrapKey(wrappedKey: WrappedKey): Promise<Buffer> {
    try {
      // Extract key name and version from the key ID
      const keyIdParts = wrappedKey.keyId.split('/');
      const keyName = keyIdParts[keyIdParts.length - 2];
      const keyVersion = keyIdParts[keyIdParts.length - 1];

      const cryptoClient = this.keyClient.getCryptographyClient(keyName, { keyVersion });
      const unwrapResult = await cryptoClient.unwrapKey('RSA-OAEP', Buffer.from(wrappedKey.wrappedKey, 'base64'));

      return Buffer.from(unwrapResult.result);
    } catch (error) {
      throw new Error(`Failed to unwrap key: ${error instanceof Error ? error.message : String(error)}`);
    }
  }

  /**
   * Encrypts data using AES-256-GCM with a newly generated DEK,
   * then wraps the DEK using Key Vault
   */
  async encryptData(plaintext: Buffer): Promise<EncryptionResult> {
    // Generate a new data encryption key
    const dataKey = this.generateDataKey();

    try {
      // Generate a random initialization vector (96 bits for GCM)
      const iv = randomBytes(12);

      // Encrypt the data using AES-256-GCM
      const cipher = createCipheriv('aes-256-gcm', dataKey, iv);
      const ciphertext = Buffer.concat([cipher.update(plaintext), cipher.final()]);
      const authTag = cipher.getAuthTag();

      // Wrap the data key using Key Vault
      const wrappedKey = await this.wrapKey(dataKey);

      return {
        ciphertext,
        iv: iv.toString('base64'),
        authTag: authTag.toString('base64'),
        wrappedKey,
      };
    } finally {
      // Ensure the data key is cleared from memory
      dataKey.fill(0);
    }
  }

  /**
   * Unwraps a DEK using Key Vault, then decrypts data using AES-256-GCM
   */
  async decryptData(
    ciphertext: Buffer,
    iv: string,
    authTag: string,
    wrappedKey: WrappedKey
  ): Promise<Buffer> {
    // Unwrap the data key using Key Vault
    const dataKey = await this.unwrapKey(wrappedKey);

    try {
      // Decrypt the data using AES-256-GCM
      const decipher = createDecipheriv('aes-256-gcm', dataKey, Buffer.from(iv, 'base64'));
      decipher.setAuthTag(Buffer.from(authTag, 'base64'));

      const plaintext = Buffer.concat([decipher.update(ciphertext), decipher.final()]);

      return plaintext;
    } catch (error) {
      throw new Error(`Failed to decrypt data: ${error instanceof Error ? error.message : String(error)}`);
    } finally {
      // Ensure the data key is cleared from memory
      dataKey.fill(0);
    }
  }
}
