{"file_text":"import { BlobServiceClient, ContainerClient } from '@azure/storage-blob';
import { KeyManager, WrappedKey } from './key-manager';

export class BlobUploader {
  private containerClient: ContainerClient;
  private keyManager: KeyManager;

  constructor(blobServiceClient: BlobServiceClient, containerName: string, keyManager: KeyManager) {
    this.containerClient = blobServiceClient.getContainerClient(containerName);
    this.keyManager = keyManager;
  }

  /**
   * Ensures the container exists, creating it if necessary
   */
  async ensureContainer(): Promise<void> {
    try {
      await this.containerClient.createIfNotExists();
    } catch (error) {
      throw new Error(`Failed to create container: ${error instanceof Error ? error.message : String(error)}`);
    }
  }

  /**
   * Encrypts and uploads data to blob storage
   * Stores encryption metadata (wrapped key, IV, auth tag) in blob metadata
   */
  async uploadEncrypted(blobName: string, data: Buffer | string): Promise<void> {
    const plaintext = Buffer.isBuffer(data) ? data : Buffer.from(data, 'utf-8');

    try {
      // Encrypt the data and wrap the DEK
      const encryptionResult = await this.keyManager.encryptData(plaintext);

      // Get blob client
      const blobClient = this.containerClient.getBlockBlobClient(blobName);

      // Store encrypted data with metadata
      await blobClient.upload(encryptionResult.ciphertext, encryptionResult.ciphertext.length, {
        metadata: {
          encrypted: 'true',
          iv: encryptionResult.iv,
          authTag: encryptionResult.authTag,
          wrappedKey: encryptionResult.wrappedKey.wrappedKey,
          keyId: encryptionResult.wrappedKey.keyId,
        },
      });
    } catch (error) {
      if (error instanceof Error && error.message.includes('wrap key')) {
        throw new Error(`Key Vault error during upload: ${error.message}`);
      } else if (error instanceof Error && error.message.includes('BlobServiceClient')) {
        throw new Error(`Blob Storage error during upload: ${error.message}`);
      }
      throw new Error(`Failed to upload encrypted blob: ${error instanceof Error ? error.message : String(error)}`);
    }
  }

  /**
   * Downloads and decrypts data from blob storage
   * Retrieves encryption metadata from blob metadata and uses Key Vault to unwrap the DEK
   */
  async downloadDecrypted(blobName: string): Promise<Buffer> {
    try {
      // Get blob client
      const blobClient = this.containerClient.getBlockBlobClient(blobName);

      // Check if blob exists
      const exists = await blobClient.exists();
      if (!exists) {
        throw new Error(`Blob '${blobName}' does not exist`);
      }

      // Download blob properties and metadata
      const properties = await blobClient.getProperties();
      const metadata = properties.metadata;

      if (!metadata || metadata.encrypted !== 'true') {
        throw new Error('Blob is not encrypted or missing encryption metadata');
      }

      // Validate required metadata
      if (!metadata.iv || !metadata.authTag || !metadata.wrappedKey || !metadata.keyId) {
        throw new Error('Blob is missing required encryption metadata');
      }

      // Download blob content
      const downloadResponse = await blobClient.download();
      if (!downloadResponse.readableStreamBody) {
        throw new Error('Failed to download blob content');
      }

      // Read stream to buffer
      const ciphertext = await this.streamToBuffer(downloadResponse.readableStreamBody);

      // Reconstruct wrapped key
      const wrappedKey: WrappedKey = {
        wrappedKey: metadata.wrappedKey,
        keyId: metadata.keyId,
      };

      // Decrypt the data
      const plaintext = await this.keyManager.decryptData(
        ciphertext,
        metadata.iv,
        metadata.authTag,
        wrappedKey
      );

      return plaintext;
    } catch (error) {
      if (error instanceof Error && error.message.includes('unwrap key')) {
        throw new Error(`Key Vault error during download: Key may be disabled or deleted`);
      } else if (error instanceof Error && error.message.includes('does not exist')) {
        throw error;
      }
      throw new Error(`Failed to download and decrypt blob: ${error instanceof Error ? error.message : String(error)}`);
    }
  }

  /**
   * Helper method to convert a readable stream to a buffer
   */
  private async streamToBuffer(readableStream: NodeJS.ReadableStream): Promise<Buffer> {
    return new Promise((resolve, reject) => {
      const chunks: Buffer[] = [];
      readableStream.on('data', (chunk) => {
        chunks.push(Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk));
      });
      readableStream.on('end', () => {
        resolve(Buffer.concat(chunks));
      });
      readableStream.on('error', reject);
    });
  }
}
