{"file_text":"import { createAzureConfig } from './config';
import { KeyManager } from './key-manager';
import { BlobUploader } from './blob-uploader';

async function main() {
  console.log('=== Azure Encrypted Blob Storage Demo ===\n');

  try {
    // Initialize Azure connections
    console.log('Initializing Azure connections...');
    const config = createAzureConfig();
    console.log(`✓ Connected to Key Vault: ${config.keyClient.vaultUrl}`);
    console.log(`✓ Using encryption key: ${config.keyName}`);
    console.log(`✓ Connected to Blob Storage container: ${config.containerName}\n`);

    // Create key manager and blob uploader
    const keyManager = new KeyManager(config.keyClient, config.keyName);
    const blobUploader = new BlobUploader(config.blobServiceClient, config.containerName, keyManager);

    // Ensure container exists
    await blobUploader.ensureContainer();

    // Sample data to encrypt and upload
    const sampleText = 'This is a secret message that will be encrypted with AES-256-GCM and stored in Azure Blob Storage!';
    const blobName = `demo-encrypted-${Date.now()}.txt`;

    console.log('--- ENCRYPTION & UPLOAD ---');
    console.log(`Original text: "${sampleText}"`);
    console.log(`Blob name: ${blobName}\n`);

    // Encrypt and upload
    console.log('Encrypting data locally with AES-256-GCM...');
    await blobUploader.uploadEncrypted(blobName, sampleText);
    console.log('✓ Data encrypted and uploaded successfully\n');

    // Retrieve encryption metadata for demonstration
    const blobClient = config.blobServiceClient
      .getContainerClient(config.containerName)
      .getBlockBlobClient(blobName);
    const properties = await blobClient.getProperties();
    const metadata = properties.metadata!;

    console.log('Encryption metadata stored in blob:');
    console.log(`  Key Vault Key ID: ${metadata.keyId}`);
    console.log(`  Wrapped DEK (base64): ${metadata.wrappedKey.substring(0, 64)}...`);
    console.log(`  IV (base64): ${metadata.iv}`);
    console.log(`  Auth Tag (base64): ${metadata.authTag}\n`);

    console.log('--- DOWNLOAD & DECRYPTION ---');
    console.log('Downloading encrypted blob...');
    console.log('Unwrapping DEK using Key Vault...');
    console.log('Decrypting data locally...\n');

    // Download and decrypt
    const decryptedBuffer = await blobUploader.downloadDecrypted(blobName);
    const decryptedText = decryptedBuffer.toString('utf-8');

    console.log('✓ Data downloaded and decrypted successfully');
    console.log(`Decrypted text: "${decryptedText}"\n`);

    // Verify round-trip
    if (sampleText === decryptedText) {
      console.log('✓ VERIFICATION PASSED: Decrypted text matches original!');
    } else {
      console.log('✗ VERIFICATION FAILED: Decrypted text does not match original');
    }

    console.log('\n=== Demo completed successfully ===');
  } catch (error) {
    console.error('\n✗ Error occurred:');
    if (error instanceof Error) {
      console.error(`  ${error.message}`);
      if (error.stack) {
        console.error('\nStack trace:');
        console.error(error.stack);
      }
    } else {
      console.error(error);
    }
    process.exit(1);
  }
}

main();
